import React,{useEffect,useLayoutEffect,useRef} from 'react';
import {ActivityIndicator,Animated,Keyboard,StyleSheet,useWindowDimensions,View} from 'react-native';
import {SafeAreaProvider,useSafeAreaInsets} from 'react-native-safe-area-context';
import {StatusBar} from 'expo-status-bar';
import {BlurTargetView} from 'expo-blur';
import {LinearGradient} from 'expo-linear-gradient';
import {Camera,CameraOff,Compass,Layers,Leaf,LocateFixed,Mic,X} from 'lucide-react-native';
import {AppProvider,useApp} from './src/AppContext';
import {ThemeProvider,useTheme} from './src/theme';
import RuntimeMap from './src/platform/RuntimeMap';
import {Action,Copy,Glass,IconButton,Notice} from './src/components/Glass';
import {LiquidNav} from './src/components/LiquidNav';
import {Sheet} from './src/components/Sheet';
import {SearchGlass} from './src/components/SearchGlass';
import {TouchlessControl} from './src/components/TouchlessControl';
import {MotionPressable as Pressable} from './src/components/MotionPressable';
import {AuthScreen} from './src/screens/AuthScreen';
import {HomeScreen,PlanScreen} from './src/screens/HomePlan';
import {SearchScreen} from './src/screens/SearchScreen';
import {NearbyScreen,LayersScreen,LiveScreen,TimetableScreen,CabsScreen} from './src/screens/DiscoverScreens';
import {TripsScreen,BookingScreen,TicketScreen} from './src/screens/TicketScreens';
import {ProfileScreen,HistoryScreen,RewardsScreen,ImpactScreen,SettingsScreen} from './src/screens/AccountScreens';
import {ChatScreen,ExplainScreen} from './src/screens/AiScreens';
import {RoutePreviewScreen} from './src/features/routing/RoutePreviewScreen';
import {CommuterProfileScreen} from './src/features/profile/CommuterProfileScreen';
import {panelLayout} from './src/layout';
const titles={preview:'Explore your route',commuter:'Your daily commute',home:'Good to go.',plan:'Your way through Nagpur',nearby:'Around you',trips:'Your journeys',profile:'A little more you',search:'Find your place',layers:'Your map, your view',live:'The city in motion',timetable:'Know your bus',cabs:'The last mile',chat:'SafarBot',explain:'A clearer journey',rewards:'Green rewards',impact:'Your impact',saved:'Saved journeys',recents:'Recent journeys',booking:'Your travel pass',ticket:'Your digital pass',settings:'Profile & preferences'};
function PanelContent(){const {panel}=useApp();switch(panel){case'preview':return <RoutePreviewScreen/>;case'commuter':return <CommuterProfileScreen/>;case'home':return <HomeScreen/>;case'plan':return <PlanScreen/>;case'nearby':return <NearbyScreen/>;case'trips':return <TripsScreen/>;case'profile':return <ProfileScreen/>;case'search':return <SearchScreen/>;case'layers':return <LayersScreen/>;case'live':return <LiveScreen/>;case'timetable':return <TimetableScreen/>;case'cabs':return <CabsScreen/>;case'chat':return <ChatScreen/>;case'explain':return <ExplainScreen/>;case'rewards':return <RewardsScreen/>;case'impact':return <ImpactScreen/>;case'saved':return <HistoryScreen saved/>;case'recents':return <HistoryScreen/>;case'booking':return <BookingScreen/>;case'ticket':return <TicketScreen/>;case'settings':return <SettingsScreen/>;default:return null}}
function AppSurface(){const app=useApp();const t=useTheme();const safe=useSafeAreaInsets();const {width,height}=useWindowDimensions();const fade=useRef(new Animated.Value(1)).current;const panel=app.panel;const authVisible=!app.auth.user||app.authMode==='update';const footerInset=app.mapStyle==='satellite'?54:0;const layout=panelLayout(width,height,safe.bottom,app.keyboard,app.expanded,app.collapsed,safe.top,footerInset);
  useEffect(()=>{if(app.ready)void app.rpc('appearance',{night:t.dark,reduceMotion:t.reduceMotion,contrast:t.contrastLevel,colors:t.c,safeBottom:safe.bottom}).catch(()=>{})},[app.ready,t.reduceMotion,t.contrastLevel,t.dark,t.appearance,safe.bottom]);
  useLayoutEffect(()=>{fade.stopAnimation();fade.setValue(t.reduceMotion?1:.96);const motion=Animated.timing(fade,{toValue:1,duration:t.reduceMotion?0:180,useNativeDriver:true,isInteraction:false});motion.start();return()=>motion.stop()},[panel,t.reduceMotion]);
  useEffect(()=>{if(app.ready)app.rpc('viewport',{fit:app.collapsed&&['plan','live','cabs'].includes(panel||'')?panel:undefined,top:app.keyboard?20:safe.top+104,bottom:panel&&!layout.landscape?layout.height+layout.bottom+10:safe.bottom+105+footerInset,left:panel&&layout.landscape?(layout.width||0)+26:0}).catch(()=>{})},[app.ready,width,height,panel,app.collapsed,app.expanded,app.keyboard,safe.bottom,footerInset]);
  return <View style={{flex:1,backgroundColor:t.c.paper}}>
    <StatusBar style={t.dark?'light':'dark'}/>
    <BlurTargetView ref={t.blurRef} style={StyleSheet.absoluteFill}>
      <RuntimeMap ref={app.mapRef} onMessage={app.onMessage}/>
      {t.dark&&<View pointerEvents="none" style={[StyleSheet.absoluteFill,{backgroundColor:'#092c2314'}]}/>}
      <LinearGradient pointerEvents="none" colors={t.dark?['#06121966','#06121900']:['#f9fcfa45','#f9fcfa00']} style={{position:'absolute',top:0,left:0,right:0,height:safe.top+140}}/>
      <LinearGradient pointerEvents="none" colors={t.dark?['#06121900','#06121935']:['#f9fcfa00','#f9fcfa25']} style={{position:'absolute',bottom:0,left:0,right:0,height:safe.bottom+110}}/>
    </BlurTargetView>
    {authVisible?<AuthScreen/>:<>
      {!app.keyboard&&<View pointerEvents="box-none" style={{position:'absolute',top:safe.top+12,left:20,right:20,gap:14}}>
        <View style={{flexDirection:'row',alignItems:'center',gap:8}}>
          <Glass level={1} style={{borderRadius:22,flexShrink:1}}><View style={{minHeight:44,paddingHorizontal:12,flexDirection:'row',alignItems:'center',gap:7}}>
            <Leaf size={19} color={t.c.accent} strokeWidth={1.6}/><Copy size={18} weight="600">eco-move</Copy><Copy size={9} muted weight="600" style={{letterSpacing:1.7,marginLeft:2}}>NAGPUR</Copy>
          </View></Glass><View style={{flex:1}}/>
          <Pressable accessibilityLabel="Open profile" accessibilityRole="button" onPress={()=>app.navigate('profile')} style={{borderRadius:22}}>
            {({pressed})=><Glass level={1} state={pressed?'pressed':'default'} style={{width:44,height:44,borderRadius:22}}><View style={{flex:1,justifyContent:'center',alignItems:'center'}}><Copy weight="600" size={15}>{(app.auth.profile?.fullName||app.auth.user?.user_metadata?.full_name||'N')[0]}</Copy></View></Glass>}
          </Pressable>
        </View>
        {!app.picking&&<SearchGlass style={layout.landscape&&panel?{marginLeft:(layout.width||0)+10}:undefined} onPress={()=>app.search('place')} label={app.searchedPlace?.name||'Where would you like to go?'}/>}
      </View>}
      {!app.keyboard&&!app.picking&&(!panel||app.collapsed||!app.expanded)&&<View style={{position:'absolute',top:safe.top+134,right:17,gap:10}}><View style={{flexDirection:layout.landscape?'row':'column',gap:10}}><IconButton label="Map layers" icon={Layers} onPress={()=>app.open('layers')}/><IconButton label="Locate me on map" icon={LocateFixed} onPress={()=>app.locate(panel==='nearby'?'anchor':'origin')}/></View><View style={{flexDirection:layout.landscape?'row':'column',justifyContent:'flex-end',gap:10}}><IconButton label={app.assistantActive?'Stop voice assistant':'Open voice assistant'} icon={Mic} onPress={app.toggleAssistant}/><IconButton label={app.gestureEnabled?'Turn off touchless map control':'Turn on touchless map control'} icon={app.gestureEnabled?Camera:CameraOff} onPress={()=>app.setGestureEnabled(!app.gestureEnabled)}/></View></View>}
      {app.picking&&<View style={{position:'absolute',top:safe.top+70,left:18,right:18}}><Glass level={4} style={{borderRadius:23}}><View style={{paddingHorizontal:17,paddingVertical:10,flexDirection:'row',gap:8,alignItems:'center'}}><MapPinIcon color={t.c.accent} size={20}/><Copy size={14} weight="500" style={{flex:1}}>Tap the map to choose {app.picking.includes('origin')?'your starting point':app.picking==='anchor'?'an area':'a location'}.</Copy><Pressable accessibilityLabel="Cancel map selection" accessibilityRole="button" onPress={()=>{app.setPicking(null);app.setCollapsed(false)}} style={{width:44,height:44,alignItems:'center',justifyContent:'center'}}><X size={20} color={t.c.ink}/></Pressable></View></Glass></View>}
      {panel&&<Sheet footerInset={footerInset} contentKey={panel} title={titles[panel]} subtitle={app.picking?'Map selection is active':panel==='home'?'LESS RUSH. MORE POSSIBILITY.':undefined} collapsed={app.collapsed} expanded={app.expanded} keyboard={app.keyboard} onCollapse={()=>{Keyboard.dismiss();app.setCollapsed(true)}} onExpand={()=>{app.setCollapsed(false);app.setExpanded(!app.expanded)}} onClose={app.close} onBack={app.stack.length>1?app.back:undefined} command={['search','booking','ticket','chat'].includes(panel)}><Animated.View style={{opacity:fade,transform:[{translateY:fade.interpolate({inputRange:[.96,1],outputRange:[4,0],extrapolate:'clamp'})}],gap:15}}>{app.error?<Notice error>{app.error}</Notice>:null}{app.runtimeError?<Notice error>{app.runtimeError}</Notice>:null}<PanelContent/></Animated.View></Sheet>}
      {!panel&&app.searchedPlace&&<View style={{position:'absolute',bottom:safe.bottom+108+footerInset,left:20,right:20}}><Glass level={2}><View style={{padding:18,gap:12}}><Copy size={21} weight="500">{app.searchedPlace.name}</Copy><Action label="Directions here" icon={Compass} selected onPress={()=>app.directions(app.searchedPlace!)}/></View></Glass></View>}
      {!panel&&!app.searchedPlace&&<View style={{position:'absolute',bottom:safe.bottom+108+footerInset,left:20,right:20,alignItems:'center'}}><Action label="Explore Nagpur" icon={Compass} onPress={()=>app.navigate('home')} compact/></View>}
      <LiquidNav footerInset={footerInset} tab={app.tab} onSelect={app.navigate} hidden={!!app.keyboard||!!app.picking}/>
      {app.gestureRunning&&<View style={{position:'absolute',top:safe.top+(height<500?10:126),left:16,zIndex:20}}><TouchlessControl/></View>}
      {!app.ready&&<View style={[StyleSheet.absoluteFill,{backgroundColor:t.c.paper+'e8',alignItems:'center',justifyContent:'center',gap:15}]}>{app.runtimeError?<View style={{padding:24,gap:16,maxWidth:420}}><Notice error>{app.runtimeError}</Notice><Action label="Retry map startup" onPress={app.retryRuntime}/></View>:<><ActivityIndicator color={t.c.accent}/><Copy>Preparing your city…</Copy></>}</View>}
    </>}
  </View>;
}
const MapPinIcon=LocateFixed;
export default function App(){return <SafeAreaProvider><ThemeProvider><AppProvider><AppSurface/></AppProvider></ThemeProvider></SafeAreaProvider>}

import React, {useEffect,useState,useRef,useMemo} from 'react';
import {createRoot} from 'react-dom/client';
import L from 'leaflet';
import MapView from '@/components/MapView';
import {AuthProvider,useAuth} from '@/context/AuthContext';
import {supabase} from '@/supabaseClient';
import * as routing from '@/lib/routing';
import * as places from '@/lib/placesSearch';
import * as nearby from '@/lib/nearby';
import * as poi from '@/lib/nagpurPlaces';
import * as live from '@/lib/liveBus';
import * as timetable from '@/lib/busTimetableService';
import * as ai from '@/lib/n8nAiService';
import * as uber from '@/lib/uberApi';
import * as ticketing from '@/lib/ticketing';
import * as tickets from '@/services/ticketService';
import * as saved from '@/services/savedJourneysService';
import * as recent from '@/services/recentJourneysService';
import * as rewards from '@/services/ecoRewardsService';
import {sendTicketConfirmationEmail,generateTicketEmailHtml} from '@/services/emailService';
import QRCode from 'qrcode';
import {POPULAR_SAVED_PLACES,POPULAR_ROUTE_PRESETS,REWARD_MILESTONES,getUberDeepLink,ticketQrPayload,paymentQrPayload} from './source-constants';
import {issueFromSource} from './source-issue';
import {satelliteController} from './satellite';
import {N8N_CONFIG} from '../src/generated/serviceConfig';
import {voiceCommand,cancelVoice} from './voice';
import {useRoutePreview} from './features/maps/useRoutePreview';
import * as commuter from '@/services/commuterProfileService';
import {invalidateProfileCache} from '@/services/profileService';
import {searchVoicePlaces} from './voicePlaces';
const PreservedMap = React.memo(MapView);

let viewport={top:100,bottom:120,left:0};
let reduceMapMotion=false;
L.Map.addInitHook(function(this:L.Map){
  window.EcoMap=this;
  // Camera padding is presentation only. All geographic data and plotting stay in MapView.
  const fit=this.fitBounds.bind(this),fly=this.flyTo.bind(this);
  this.fitBounds=(bounds:any,options:any={})=>fit(bounds,{...options,...(reduceMapMotion?{animate:false}:{}),paddingTopLeft:[viewport.left+24,viewport.top],paddingBottomRight:[24,Math.min(viewport.bottom,this.getSize().y*.7)]});
  this.flyTo=(center:any,zoom?:number,options?:any)=>{const z=zoom??this.getZoom();const p=this.project(L.latLng(center),z);const adjusted=this.unproject(L.point(p.x-viewport.left/2,p.y+(viewport.bottom-viewport.top)/2),z);return reduceMapMotion?this.setView(adjusted,z,{animate:false}):fly(adjusted,z,options)};
  this.whenReady(()=>{window.EcoSatellite=satelliteController(this,import.meta.env.VITE_GOOGLE_MAPS_API_KEY||'',value=>window.EcoSend({type:'mapEvent',name:'satelliteState',value}));});
  const outside=(e:L.LeafletMouseEvent)=>{
    const target=e.originalEvent?.target as Element|null;
    if(target?.closest?.('.leaflet-interactive,.leaflet-marker-icon,.leaflet-popup,.leaflet-control'))return;
    window.EcoSend({type:'mapEvent',name:'backgroundTap',value:null});
  };
  this.on('click',outside);
  this.on('unload',()=>{this.off('click',outside);window.EcoSatellite?.destroy();});
});
const send=window.EcoSend;
const initialMap={journey:null,origin:null,destination:null,showNetwork:false,showBusStops:false,showMetroStations:false,mapStyle:'carto',nearbyMarkers:[],poiMarkers:[]};
function Engine(){
  const auth=useAuth();
  const preview=useRoutePreview();
  const [props,setProps]=useState<any>(initialMap);
  const currentProps=useRef(props);currentProps.current=props;
  useEffect(()=>{send({type:'auth',user:auth.user,profile:auth.profile,loading:auth.loading,isDemoUser:auth.isDemoUser})},[auth.user,auth.profile,auth.loading]);
  useEffect(()=>{
    const userId=()=>{if(!auth.user)throw new Error('Please sign in to continue.');return auth.user.id;};
    const actions:Record<string,(a:any)=>any>={
      bootstrap:()=>({stats:routing.networkStats,places:POPULAR_SAVED_PLACES,presets:POPULAR_ROUTE_PRESETS,rewards:REWARD_MILESTONES,metroLines:ticketing.NAGPUR_METRO_LINES,busRoutes:ticketing.getAvailableBusRoutes()}),
      demo:()=>auth.loginAsDemoUser(),
      login:a=>a.method==='phone'?auth.signInWithPhone(a.contact,a.password):auth.signInWithEmail(a.contact,a.password),
      signup:a=>a.method==='phone'?auth.signUpWithPhone(a.phone,a.password,a.name,a.email):auth.signUpWithEmail(a.email,a.password,a.name,a.phone),
      verify:a=>a.method==='phone'?auth.verifyOtp(a.contact,a.code):auth.verifyEmailOtp(a.contact,a.code),
      resend:a=>a.method==='phone'?supabase.auth.resend({type:'signup',phone:a.contact}):auth.resendSignupOtp(a.contact),
      reset:a=>supabase.auth.resetPasswordForEmail(a.email,{redirectTo:a.redirectTo}),
      updatePassword:a=>auth.updatePassword(a.password),
      oauth:()=>supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:'ecomove://auth/callback',skipBrowserRedirect:true}}),
      callback:async a=>{
        const url=new URL(a.url);const p=new URLSearchParams(url.hash.slice(1)||url.search.slice(1));
        if(p.get('error_description'))throw Error(p.get('error_description')!);
        if(p.get('access_token'))return supabase.auth.setSession({access_token:p.get('access_token')!,refresh_token:p.get('refresh_token')!});
        if(p.get('code'))return supabase.auth.exchangeCodeForSession(p.get('code')!);
        throw Error('The sign-in link has no session. Please request a fresh link.');
      },
      logout:()=>{preview.control({action:"stop"});invalidateProfileCache();return auth.signOut()},
      commuter:()=>commuter.fetchCommuterProfile(userId()),
      saveCommuter:a=>commuter.saveCommuterProfile(userId(),a.profile,!!a.skipped),
      preview:a=>{userId();return preview.control(a)},
      previewStatus:()=>preview.status(),
      profile:a=>auth.updateUserProfile(a),
      searchLocal:a=>places.searchLocalPlaces(a.query,20),
      voicePlaces:a=>searchVoicePlaces(a.query),
      searchOnline:a=>places.searchOnlinePlaces(a.query),
      plan:async a=>{userId();return routing.planJourney(a.origin,a.destination,a.preference,a.departureMin)},
      enrich:async a=>{userId();try{return await Promise.race([routing.enrichWalkLegs(a.journey,a.origin,a.destination,a.preference),new Promise<any>(r=>setTimeout(()=>r(a.journey),3500))])}catch{return a.journey}},
      fallback:a=>routing.planFallbackDrivingJourney(a.origin,a.destination,a.departureTime||'now'),
      recordRecent:a=>recent.recordUserRecentJourney(userId(),a.origin,a.destination),
      saved:()=>saved.fetchUserSavedJourneys(userId()),
      save:a=>saved.addUserSavedJourney(userId(),a),
      deleteSaved:a=>saved.deleteUserSavedJourney(userId(),a.id),
      recents:()=>recent.fetchUserRecentJourneys(userId()),
      clearRecents:()=>recent.clearUserRecentJourneys(userId()),
      nearby:a=>nearby.findNearby(a.anchor,a.radius),
      pois:a=>poi.fetchLiveNearbyPOIs(a.anchor.lat,a.anchor.lon,a.category,30),
      cityPois:a=>poi.fetchNagpurWidePOIs(a.anchor.lat,a.anchor.lon,a.category),
      localPois:a=>poi.findNearestPOIs(a.anchor.lat,a.anchor.lon,a.category,30),
      liveSearch:a=>live.searchLiveBusRoutes(a.query,a.limit||30),
      liveDetails:a=>live.fetchLiveRouteDetails(a.id),
      liveTelemetry:a=>live.fetchLiveRouteInfo(a.ids,a.stopIds),
      nearbyBuses:a=>live.fetchNearbyLiveBuses(a.anchor.lat,a.anchor.lon,a.radius),
      timetable:a=>timetable.getBusTimetable(a.busNumber,a.routeName,a.fromStop,a.toStop),
      cabs:a=>uber.findUberCabOptions(a.origin.lat,a.origin.lon,a.destination.lat,a.destination.lon),
      cabLink:a=>getUberDeepLink(a.origin,a.destination,a.product),
      chat:a=>ai.askAiTransitChatbot(a.query,a.context,N8N_CONFIG.production),
      intent:a=>ai.executeAiSearchQuery(a.query,a.location,N8N_CONFIG.production),
      voice:a=>{userId();return voiceCommand(a)},
      voiceCancel:a=>cancelVoice(a.id),
      explain:a=>ai.explainRouteWithN8n(a.journey,a.origin,a.destination,N8N_CONFIG.production,a.index,a.language),
      compare:a=>ai.compareRoutesWithN8n(a.journeys,a.origin,a.destination,N8N_CONFIG.production,a.language),
      clearExplanation:a=>{ai.clearCachedRouteExplanation(a.journey,a.origin,a.destination,a.index,a.language);return true},
      clearComparison:a=>{ai.clearCachedRouteComparison(a.journeys,a.origin,a.destination,a.language);return true},
      tickets:()=>tickets.fetchUserTickets(userId()),
      deleteTicket:a=>tickets.deleteUserTicket(userId(),a.id),
      transitLegs:a=>ticketing.convertJourneyLegsToTransitLegs(a.legs),
      fare:a=>ticketing.calculateMultiLegFareSummary(a),
      issue:async a=>{userId();return issueFromSource({...a,txnRef:ticketing.generateTransactionRef(),fareSummary:ticketing.calculateMultiLegFareSummary({category:a.selectedCategory,legs:a.legs,passengers:a.passengers})},auth)},
      scan:async a=>{userId();const t=(await tickets.fetchUserTickets(userId())).find(t=>t.id===a.id);if(!t)throw Error('Ticket not found');if(t.status!=='active'||t.currentLegStep==='completed')throw Error('This pass is no longer active.');ticketing.saveIssuedTicket(t);const r=ticketing.simulateGateScan(a.id);if(r.updatedTicket)await tickets.saveUserTicket(userId(),r.updatedTicket);return r},
      qr:a=>QRCode.toDataURL(a.payload,{width:560,margin:2,errorCorrectionLevel:'M'}),
      ticketQr:a=>QRCode.toDataURL(JSON.stringify(ticketQrPayload(a.ticket,a.ticket.status==='used'||a.ticket.currentLegStep==='completed'),null,2),{width:560,margin:2,errorCorrectionLevel:'M'}),
      paymentQr:a=>QRCode.toDataURL(paymentQrPayload(a.fare,a.source,a.destination),{width:440,margin:1,errorCorrectionLevel:'M'}),
      ticketHtml:async a=>generateTicketEmailHtml({recipientEmail:auth.user?.email||'',userName:auth.profile?.fullName||'Commuter',ticket:a.ticket,qrCodeDataUrl:await QRCode.toDataURL(a.ticket.qrPayload,{width:280,margin:1})}),
      email:a=>sendTicketConfirmationEmail({recipientEmail:a.recipient,userName:auth.profile?.fullName,ticket:a.ticket}),
      rewards:()=>rewards.fetchUserEcoStats(userId()),
      claim:a=>rewards.claimUserRewardMilestone(userId(),a.id),
      map:a=>{setProps((p:any)=>{let changed=false;const next={...p};for(const key of Object.keys(a)){const same=JSON.stringify(p[key])===JSON.stringify(a[key]);next[key]=same?p[key]:a[key];changed=changed||!same;}return changed?next:p});return true},
      appearance:a=>{reduceMapMotion=!!a.reduceMotion;const root=document.documentElement;root.dataset.night=a.night?'true':'false';for(const [key,value]of Object.entries(a.colors||{}))root.style.setProperty('--eco-'+key,String(value));root.style.setProperty('--eco-safe-bottom',`${Math.max(0,Number(a.safeBottom)||0)}px`);root.dataset.contrast=a.contrast>=50?'enhanced':'standard';return true},
      zoom:a=>{window.EcoMap?.setZoom(window.EcoMap.getZoom()+a.delta);return true},
      center:a=>{window.EcoMap?.flyTo([a.lat,a.lon],a.zoom||15,{duration:.6});return true},
      resize:()=>{setTimeout(()=>window.EcoMap?.invalidateSize({pan:false}),100);return true},
      viewport:a=>{viewport=a;window.EcoMap?.invalidateSize({pan:false});if(a.fit){const p=currentProps.current;const points=a.fit==='live'?p.liveRoute?.polyline:a.fit==='cabs'?p.cabPolyline:p.journey?.legs.flatMap((l:any)=>l.path.map((v:any)=>[v.lat,v.lon]));if(points?.length>1)window.EcoMap?.fitBounds(points,{animate:false});}return true},
    };
    window.EcoReceive=async m=>{
      if(m.type==='httpResult'){window.dispatchEvent(new CustomEvent('eco-http',{detail:m}));return;}
      if(m.type!=='rpc')return;
      try{const fn=actions[m.method];if(!fn)throw Error('Unknown app action');const result=await fn(m.args||{});if(result?.error&&['login','signup','verify','resend','reset','updatePassword','oauth','callback','profile'].includes(m.method))throw Error(result.error.message||String(result.error));send({type:'result',id:m.id,value:result??null})}
      catch(e:any){send({type:'result',id:m.id,error:e?.message||String(e)})}
    };
  },[auth,preview.control,preview.status]);
  useEffect(()=>{send({type:'ready'});return()=>{}},[]);
  useEffect(()=>{void window.EcoSatellite?.select(props.mapStyle==='satellite',props.mapStyle!=='roadmap')},[props.mapStyle]);
  const events=useMemo(()=>{const event=(name:string)=>(value:any)=>send({type:'mapEvent',name,value});return {onMapClick:event('pick'),onSelectNearbyBus:event('nearbyBus'),onSelectLiveStop:event('liveStop'),onSelectBusTimetable:event('timetable'),onDirectionsToSearchedLocation:event('directions'),onDirectionsToPoi:event('directions')}},[]);
  return <PreservedMap {...props} mapStyle={props.mapStyle==='satellite'?'carto':props.mapStyle} {...events}>{preview.node}</PreservedMap>;
}
export function mount(){createRoot(document.getElementById('root')!).render(<AuthProvider><Engine/></AuthProvider>)}

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import {
  ActivityIndicator,
  Animated,
  Easing,
  Platform,
  StyleSheet,
  Text,
  TextInput,
  TextInputProps,
  View,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { BlurView } from 'expo-blur';
import { GlassView, isLiquidGlassAvailable } from 'expo-glass-effect';
import { LinearGradient } from 'expo-linear-gradient';
import { useTheme } from '../theme';
import { glassGeometry, glassMaterial } from '../glassTokens';
import { MotionPressable as Pressable } from './MotionPressable';

// One backdrop sample per major surface. Cards inside it inherit its material.
const MaterialParent = createContext(false);

export type MaterialState =
  | 'default'
  | 'hover'
  | 'pressed'
  | 'active'
  | 'selected'
  | 'focused'
  | 'disabled'
  | 'loading'
  | 'success'
  | 'error';

export function Glass({
  children,
  level = 2,
  state = 'default',
  style,
  blur = true,
  specular = false,
  moving = false,
  isolated = false,
  materialStyle,
}: {
  children?: React.ReactNode;
  level?: 1 | 2 | 3 | 4;
  state?: MaterialState;
  style?: StyleProp<ViewStyle>;
  moving?: boolean;
  blur?: boolean;
  specular?: boolean;
  isolated?: boolean;
  materialStyle?: StyleProp<ViewStyle> | any;
}) {
  const t = useTheme();
  const parentMaterial = useContext(MaterialParent);
  const nested = parentMaterial && !isolated;
  const samplesBackdrop = blur && !nested;
  const contrastRatio = Math.max(0, Math.min(100, t.contrastLevel)) / 100;
  // CSS support detection is presentation-only. The fallback keeps the same
  // readable tint; Android avoids the existing WebView backdrop capture defect.
  const webBlur = Platform.OS !== 'web' || (typeof CSS !== 'undefined' &&
    (CSS.supports('backdrop-filter', 'blur(1px)') || CSS.supports('-webkit-backdrop-filter', 'blur(1px)')));
  const material = glassMaterial(t.appearance, t.dark, t.contrastLevel, level, nested, webBlur && Platform.OS !== 'android');
  const backdrop = samplesBackdrop && material.blur > 0 && webBlur && Platform.OS !== 'android';
  const nativeGlass = Platform.OS === 'ios' && t.appearance === 'liquid' && isLiquidGlassAvailable() && contrastRatio < .25;
  const illumination = useRef(new Animated.Value(state === 'focused' ? 1 : state === 'hover' ? .65 : state === 'pressed' ? 0 : .2)).current;
  const initialMaterial = useRef(true);
  const selection = useRef(new Animated.Value(['active', 'selected', 'success'].includes(state) ? 1 : 0)).current;
  const reflection = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (!moving || !material.flowing || t.reduceMotion || t.contrast || !t.active) {
      reflection.setValue(0);
      return;
    }
    const motion = Animated.loop(Animated.sequence([
      Animated.timing(reflection, { toValue: 1, duration: glassGeometry.motion.reflection, easing: Easing.inOut(Easing.sin), useNativeDriver: true, isInteraction: false }),
      Animated.timing(reflection, { toValue: 0, duration: glassGeometry.motion.reflection, easing: Easing.inOut(Easing.sin), useNativeDriver: true, isInteraction: false }),
    ]));
    motion.start();
    return () => motion.stop();
  }, [moving, material.flowing, t.reduceMotion, t.contrast, t.active, reflection]);

  const selected = ['active', 'selected', 'success'].includes(state);
  const focused = state === 'focused';
  const pressed = state === 'pressed';
  const hover = state === 'hover';
  useEffect(() => {
    // Large service lists start at their resting material. Animate interaction
    // changes only, avoiding hundreds of invisible mount animations in Nearby.
    if (initialMaterial.current) { initialMaterial.current = false; return; }
    const animation = Animated.parallel([
      Animated.timing(illumination, { toValue: pressed ? 0 : focused ? 1 : hover ? 0.65 : 0.2, duration: t.reduceMotion ? 0 : glassGeometry.motion.feedback, useNativeDriver: true, isInteraction: false }),
      Animated.timing(selection, { toValue: selected ? 1 : 0, duration: t.reduceMotion ? 0 : glassGeometry.motion.selection, useNativeDriver: true, isInteraction: false }),
    ]);
    animation.start();
    return () => animation.stop();
  }, [pressed, focused, hover, selected, t.reduceMotion, illumination, selection]);

  const edge = state === 'error'
    ? t.c.error
    : focused
    ? t.c.accent
    : selected
    ? (t.dark ? 'rgba(168, 233, 194, 0.42)' : 'rgba(23, 99, 62, 0.40)')
    : material.edge;

  const flatRadius = StyleSheet.flatten(style)?.borderRadius ?? glassGeometry.radius.card;
  const transition = Platform.OS === 'web' ? {
    transitionProperty: 'background-color, border-color, box-shadow',
    transitionDuration: t.reduceMotion ? '0ms' : `${glassGeometry.motion.material}ms`,
    transitionTimingFunction: 'cubic-bezier(.2,.8,.2,1)',
  } as any : undefined;

  return (
    <View
      style={[
        samplesBackdrop && level > 1 && !materialStyle ? s.shadow : null,
        {
          borderRadius: flatRadius,
          shadowOpacity: !samplesBackdrop || materialStyle ? 0 : material.shadowOpacity,
          shadowRadius: !samplesBackdrop ? 0 : material.shadowRadius,
          elevation: !samplesBackdrop || level === 1 || materialStyle ? 0 : Math.min(6, level + 1),
          opacity: state === 'disabled' ? 0.5 : 1,
        },
        style,
      ]}
    >
      <View
        testID={`glass-${t.appearance}-${level}`}
        style={[
          s.surface,
          {
            borderRadius: flatRadius,
            backgroundColor: 'transparent',
          },
        ]}
      >
        <Animated.View pointerEvents="none" style={[StyleSheet.absoluteFill, { borderRadius: flatRadius, overflow: 'hidden' }, materialStyle]}>
        {backdrop && (
          nativeGlass ? (
            <GlassView
              pointerEvents="none"
              style={StyleSheet.absoluteFill}
              glassEffectStyle={level === 1 ? 'clear' : 'regular'}
              colorScheme={t.dark ? 'dark' : 'light'}
              tintColor={selected ? (t.dark ? '#4ade8025' : '#186d4e18') : undefined}
              isInteractive={false}
            />
          ) : Platform.OS === 'web' ? (
            <View pointerEvents="none" style={[StyleSheet.absoluteFill, {
              backdropFilter: `blur(${material.blur}px) saturate(${material.saturation})`,
              WebkitBackdropFilter: `blur(${material.blur}px) saturate(${material.saturation})`,
            } as any]} />
          ) : (
            <BlurView
              pointerEvents="none"
              style={StyleSheet.absoluteFill}
              intensity={material.blur}
              tint={t.dark ? 'dark' : 'light'}
            />
          )
        )}

        <View pointerEvents="none" style={[StyleSheet.absoluteFill, { backgroundColor: material.tint }, transition]} />

        {/* Selected mint luminescence */}
          <Animated.View
            pointerEvents="none"
            style={[
              StyleSheet.absoluteFill,
              { opacity: selection, backgroundColor: material.selection },
            ]}
          />

        {/* Full-surface gradients have no mid-control cutoffs or white streaks. */}
        {(specular || level >= 2 || hover || focused) && contrastRatio < 0.75 && (
          <LinearGradient
            pointerEvents="none"
            colors={
              t.dark
                ? [`rgba(234, 255, 247, ${material.highlight})`, 'rgba(234, 255, 247, 0)', `rgba(0, 15, 8, ${material.highlight * .8})`]
                : [`rgba(255, 255, 255, ${material.highlight * 2})`, 'rgba(255, 255, 255, 0)', `rgba(24, 62, 41, ${material.highlight * .5})`]
            }
            start={{ x: 0, y: 0 }}
            end={{ x: 0.7, y: 1 }}
            style={[
              StyleSheet.absoluteFill,
              { opacity: (1 - contrastRatio * 0.8) * (pressed ? 0.35 : hover || focused ? 1 : 0.8) },
            ]}
          />
        )}

        {moving && material.flowing && <Animated.View pointerEvents="none" style={{ position: 'absolute', top: 0, bottom: 0, left: -60, right: -60, opacity: 1 - contrastRatio, transform: [{ translateX: reflection.interpolate({ inputRange: [0, 1], outputRange: [-35, 35] }) }] }}>
          <LinearGradient colors={['transparent', `rgba(230,255,240,${material.reflection * .35})`, 'transparent']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 0.6 }} style={StyleSheet.absoluteFill}/>
          <LinearGradient colors={['transparent', `rgba(230,255,240,${material.reflection * 5})`, 'transparent']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }} style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 1.5 }}/>
        </Animated.View>}
        {contrastRatio < 0.85 && <Animated.View pointerEvents="none" style={[StyleSheet.absoluteFill, { opacity: illumination, backgroundColor: t.dark ? '#ffffff09' : '#ffffff20' }]}/>}
        <View pointerEvents="none" style={[StyleSheet.absoluteFill, { borderRadius: flatRadius, borderWidth: focused ? 1.5 : 1, borderColor: edge, borderTopColor: focused || state === 'error' ? edge : material.topEdge }, transition]}/>
        </Animated.View>
        <MaterialParent.Provider value={nested || samplesBackdrop}>{children}</MaterialParent.Provider>
      </View>
    </View>
  );
}

export function Copy({
  children,
  size = 15,
  muted = false,
  accent = false,
  weight = '400',
  style,
  ...rest
}: any) {
  const { c } = useTheme();
  return (
    <Text
      {...rest}
      style={[
        {
          fontSize: size,
          lineHeight: Math.round(size * 1.36),
          color: accent ? c.accent : muted ? c.muted : c.ink,
          fontWeight: weight,
          fontFamily: Platform.OS === 'web' ? '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif' : Platform.OS === 'ios' ? undefined : 'sans-serif',
          letterSpacing: size >= 24 ? -0.6 : size <= 11 ? 0.3 : -0.1,
          backgroundColor: 'transparent',
          includeFontPadding: false,
        },
        style,
      ]}
    >
      {children}
    </Text>
  );
}

export function Action({
  label,
  accessibilityLabel = label,
  icon: Icon,
  onPress,
  selected = false,
  disabled = false,
  loading = false,
  compact = false,
  quiet = false,
  danger = false,
  style,
  testID,
}: any) {
  const { c, dark } = useTheme();
  const [hover, setHover] = useState(false);
  const [focus, setFocus] = useState(false);
  const minH = compact ? 44 : 48;

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      aria-selected={selected}
      aria-busy={loading}
      accessibilityState={{ selected, disabled: disabled || loading, busy: loading }}
      testID={testID}
      disabled={disabled || loading}
      onPress={onPress}
      onHoverIn={() => setHover(true)}
      onHoverOut={() => setHover(false)}
      onFocus={() => setFocus(true)}
      onBlur={() => setFocus(false)}
      style={[{ minHeight: minH, flexShrink: 1 }, style]}
    >
      {({ pressed }) => (
        <Glass
          blur={false}
          level={selected ? 2 : 1}
          state={
            disabled
              ? 'disabled'
              : loading
              ? 'loading'
              : pressed
              ? 'pressed'
              : focus
              ? 'focused'
              : hover
              ? 'hover'
              : selected
              ? 'selected'
              : 'default'
          }
          style={{
            borderRadius: compact ? 16 : 20,
            flexGrow: 1,
          }}
        >
          <View
            style={[
              s.action,
              {
                minHeight: minH,
                paddingVertical: compact ? 8 : 11,
                paddingHorizontal: compact ? 8 : 16,
                gap: compact ? 5 : 8,
                backgroundColor: quiet ? 'transparent' : undefined,
              },
            ]}
          >
            {loading ? (
              <ActivityIndicator size="small" color={c.accent} />
            ) : Icon ? (
              <Icon
                size={compact ? 15 : 18}
                color={danger ? c.error : selected ? c.accent : c.ink}
                strokeWidth={selected ? 2 : 1.75}
              />
            ) : null}
            <Copy
              weight={selected ? '600' : '500'}
              size={compact ? 12.5 : 15}
              numberOfLines={compact ? 2 : 1}
              ellipsizeMode="tail"
              style={{
                color: danger ? c.error : selected ? c.accent : c.ink,
                flexShrink: 1,
              }}
            >
              {label}
            </Copy>
          </View>
        </Glass>
      )}
    </Pressable>
  );
}

